sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var cp = new GlideRecord('customer_project');
        cp.initialize();
        cp.short_description = "FCS paquetizados " + current.number;
        cp.description = "QO: " + current.qo + "\nCotización: " + current.quote + "\nOrden de aprovisionamiento Telmex: " + current.telmex_supply_order + "\nCaso de instalación: " + current.telmex_insta_case;
        cp.u_order_number = current.telmex_supply_order;
        cp.assignment_group = current.assignment_group;
		cp.u_packaged_id = current.sys_id;
        var cp_sysid = cp.insert();
		if (cp_sysid) {
            gs.info('Custom project insertado correctamente. sys_id: ' + cp_sysid);
        } else {
            gs.error('Error: cp.insert() no devolvió sys_id. Inserción fallida de custom project.');
        }
    } catch (error) {
        gs.error("Error al crear el custom project desde OS: " + error);
    }
})(current, previous);
